<script lang="ts">
 import {onMount} from 'svelte'
 import {initialSharing,applySharing} from '../../studies/expansion.mjs'
 let mounted=$state(false),model=$state(initialSharing()),copied=$state('')
 onMount(()=>{mounted=true})
 async function copy(){try{await navigator.clipboard.writeText('https://example.test/reports/field-notes');copied='Link copied. Access remains '+model.confirmed+'.'}catch{copied='Clipboard unavailable. Select the displayed example link to copy it.'}}
</script>
<section class="task-study" data-study="sharing" aria-label="Draft and confirmed sharing"><p>Field notes · fictional local sharing. No server permissions change.</p><p>Confirmed audience: <strong data-audience>{model.confirmed}</strong></p><fieldset disabled={!mounted}><legend class="study-sr">Sharing controls</legend><label class="study-field">Draft audience<select class="select" bind:value={model.draft}><option>Private</option><option>Named people: Maya Chen</option><option>Anyone with the link</option></select></label><p>{model.draft==='Anyone with the link'?'Anyone receiving the link would be able to read this report after Apply succeeds.':model.draft==='Private'?'Only the owner would have access.':'Maya Chen would receive read access; no invitation is actually sent.'}</p><label class="check"><input class="checkbox" type="checkbox" bind:checked={model.fail}/> Fail next apply</label><div class="study-actions"><button class="btn btn-primary" onclick={()=>model=applySharing(model)}>Apply audience</button><button class="btn" onclick={()=>model={...model,draft:model.confirmed,message:'Cancelled draft changes.'}}>Cancel audience change</button></div><p role="status">{model.message}</p><p class="specimen-url">https://example.test/reports/field-notes</p><button class="btn" onclick={copy}>Copy example link</button><p role="status">{copied}</p><button class="btn" onclick={()=>{model={...model,draft:'Private'};copied='Choose Apply to revoke local access.'}}>Prepare revocation</button><button class="btn" onclick={()=>{model=initialSharing();copied=''}}>Reset sharing</button></fieldset><noscript>The audience explanation remains readable. Controls require JavaScript.</noscript></section>
<style>.specimen-url{overflow-wrap:anywhere}</style>
